router.get('/operations/support/tickets/:id',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{
  const ticket=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user)}).select('+requesterEmailEncrypted').populate('evidenceDocumentIds','publicId description createdAt').populate('assignedUserId','name publicId role').populate('notes.actorUserId','name publicId role').populate('assignmentHistory.actorUserId','name publicId role').populate('assignmentHistory.assignedUserId','name publicId role').populate('workflowHistory.actorUserId','name publicId role');
  if(!ticket)throw new AppError('Support ticket not found.',404,'TICKET_NOT_FOUND');
  const now=new Date(),expiresAt=new Date(now.getTime()+90_000);await SupportTicketPresence.findOneAndUpdate({ticketId:ticket._id,userId:req.user._id},{$set:{country:ticket.country,expiresAt}},{upsert:true,setDefaultsOnInsert:true});
  const transferSearch=String(req.query.transferQ||'').trim().slice(0,120);
  const transferBase={status:'active',role:{$in:['support','country_admin','super_admin']},$or:[{role:'super_admin'},{country:ticket.country},{operationalCountries:ticket.country},{operationalCountries:'*'}]};
  if(transferSearch){const re=new RegExp(escapeRegex(transferSearch),'i');transferBase.$and=[{$or:[{name:re},{email:re},{publicId:re}]}];}
  const [presence,order,shipments,payments,refunds,sellerOrders,macros,transferCandidates]=await Promise.all([
    SupportTicketPresence.find({ticketId:ticket._id,userId:{$ne:req.user._id},expiresAt:{$gt:now}}).populate('userId','name publicId role').lean(),
    ticket.orderId?Order.findById(ticket.orderId).select('publicId paymentState fulfillmentState cancellationState returnState refundState totals contact createdAt').lean():null,
    ticket.orderId?Shipment.find({orderId:ticket.orderId}).select('publicId kind status mode deliveredAt failedReason updatedAt').sort({createdAt:-1}).lean():[],
    ticket.orderId?PaymentIntent.find({orderId:ticket.orderId}).select('publicId provider status amountMinor currency createdAt paidAt').sort({createdAt:-1}).lean():[],
    ticket.orderId?Refund.find({orderId:ticket.orderId}).select('publicId status amountMinor currency reason createdAt completedAt').sort({createdAt:-1}).lean():[],
    ticket.orderId?SellerOrder.find({orderId:ticket.orderId}).select('publicId storePublicId status fulfillmentStatus currency totalMinor updatedAt').lean():[],
    SupportMacro.find({country:ticket.country,active:true,$or:[{category:''},{category:ticket.category}]}).sort({title:1}).lean(),
    User.find(transferBase).select('+operationalCountries name email publicId role country').sort({name:1,_id:1}).limit(51).lean(),
  ]);
  const authorizedCandidates=transferCandidates.filter(candidate=>canSupportOperations(candidate)&&operationalCountriesFor(candidate).some(code=>code==='*'||code===ticket.country));
  const transferHasMore=authorizedCandidates.length>50,candidates=authorizedCandidates.slice(0,50);
  res.set('Cache-Control','private, no-store').render('support-ticket',{ticket,requester:supportRequester(ticket),presence,order,shipments,payments,refunds,sellerOrders,macros,transferCandidates:candidates,transferSearch,transferHasMore});
}catch(e){next(e);}});
