router.post('/operations/support/tickets/:id/transfer',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{const input=z.object({userPublicId:z.string().trim().min(4).max(120)}).parse(req.body);const t=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user),status:{$nin:['resolved','closed']}});if(!t)throw new AppError('Active support ticket not found.',404,'TICKET_NOT_FOUND');const supervisor=['country_admin','super_admin'].includes(req.user.role);if(!t.assignedUserId)throw new AppError('Claim the ticket before transferring it.',409,'TICKET_CLAIM_REQUIRED');if(!t.assignedUserId.equals(req.user._id)&&!supervisor)throw new AppError('Only the assigned operator or supervisor can transfer this ticket.',409,'TICKET_TRANSFER_FORBIDDEN');const target=await User.findOne({publicId:input.userPublicId,status:'active'}).select('+operationalCountries');if(!target||!canSupportOperations(target)||!operationalCountriesFor(target).some(code=>code==='*'||code===t.country))throw new AppError('Target support operator is not authorized for this ticket country.',422,'TICKET_TRANSFER_TARGET_INVALID');if(t.assignedUserId.equals(target._id))throw new AppError('Ticket is already assigned to that operator.',409,'TICKET_TRANSFER_SAME');const now=new Date();t.assignedUserId=target._id;t.assignedAt=now;t.assignmentHistory.push({action:'transfer',actorUserId:req.user._id,assignedUserId:target._id,at:now});if(t.status==='open')t.status='in_progress';await t.save();await writeAudit(req,'support.ticket_transferred',{targetType:'support_ticket',targetPublicId:t.publicId,country:t.country,metadata:{toUserPublicId:target.publicId}});setFlash(req,'success',`Ticket transferred to ${target.name}.`);res.redirect(`/operations/support/tickets/${encodeURIComponent(t.publicId)}`);}catch(e){next(e);}});
router.post('/operations/support/tickets/:id/reopen',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{const t=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user),status:{$in:['resolved','closed']}});if(!t)throw new AppError('Resolved support ticket not found.',404,'TICKET_NOT_FOUND');const from=t.status;t.status='open';t.resolvedAt=undefined;t.reopenedAt=new Date();t.assignedUserId=req.user._id;t.assignedAt=t.reopenedAt;t.slaDueAt=new Date(Date.now()+supportSlaHours(t.priority)*60*60*1000);t.assignmentHistory.push({action:'claim',actorUserId:req.user._id,assignedUserId:req.user._id,at:t.reopenedAt});t.workflowHistory.push({action:'reopened',actorUserId:req.user._id,fromStatus:from,toStatus:'open',note:'Support operator reopened ticket.'});await t.save();await writeAudit(req,'support.ticket_reopened',{targetType:'support_ticket',targetPublicId:t.publicId,country:t.country});res.redirect(`/operations/support/tickets/${encodeURIComponent(t.publicId)}`);}catch(e){next(e);}});
router.post('/operations/support/tickets/:id/merge',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{if(!['country_admin','super_admin'].includes(req.user.role))throw new AppError('Supervisor permission is required to merge support tickets.',403,'TICKET_MERGE_FORBIDDEN');const targetPublicId=z.string().trim().min(4).max(120).parse(req.body.targetPublicId);if(targetPublicId===req.params.id)throw new AppError('A ticket cannot be merged into itself.',422,'TICKET_MERGE_SELF');const session=await mongoose.startSession();let target;try{await session.withTransaction(async()=>{const source=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user),status:{$nin:['resolved','closed']}}).session(session);if(!source)throw new AppError('Active source ticket not found.',404,'TICKET_NOT_FOUND');target=await SupportTicket.findOne({publicId:targetPublicId,country:source.country,status:{$nin:['resolved','closed']}}).session(session);if(!target)throw new AppError('Active merge target not found in the same country.',404,'TICKET_MERGE_TARGET_NOT_FOUND');const now=new Date(),sourceStatus=source.status;source.status='closed';source.resolvedAt=now;source.mergedIntoPublicId=target.publicId;source.mergedAt=now;source.mergedByUserId=req.user._id;source.assignedUserId=undefined;source.assignedAt=undefined;source.notes.push({message:`Merged into ${target.publicId}. Continue work on the target ticket.`,actorUserId:req.user._id,internal:true});source.workflowHistory.push({action:'merged',actorUserId:req.user._id,fromStatus:sourceStatus,toStatus:'closed',targetTicketPublicId:target.publicId,note:'Supervisor merged duplicate ticket.'});target.mergedTicketPublicIds.addToSet(source.publicId);target.notes.push({message:`Duplicate ticket ${source.publicId} was merged into this ticket.`,actorUserId:req.user._id,internal:true});target.workflowHistory.push({action:'merge_received',actorUserId:req.user._id,targetTicketPublicId:source.publicId,note:'Duplicate ticket merged here.'});await source.save({session});await target.save({session});});}finally{await session.endSession();}await writeAudit(req,'support.ticket_merged',{targetType:'support_ticket',targetPublicId:req.params.id,country:target.country,metadata:{mergedInto:target.publicId}});setFlash(req,'success',`Ticket merged into ${target.publicId}.`);res.redirect(`/operations/support/tickets/${encodeURIComponent(target.publicId)}`);}catch(e){next(e);}});
router.post('/operations/support/macros',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{const input=z.object({country:z.string().trim().length(2),title:z.string().trim().min(2).max(120),body:z.string().trim().min(3).max(4000),category:z.enum(['','order','payment','delivery','return','refund','account','product','seller','other']).default('')}).parse(req.body);const country=input.country.toUpperCase();if(req.user.role!=='super_admin')assertOperationalCountry(req.user,country);const macro=await SupportMacro.create({publicId:publicId('mac'),country,title:input.title,body:input.body,category:input.category,createdByUserId:req.user._id,updatedByUserId:req.user._id});await writeAudit(req,'support.macro_created',{targetType:'support_macro',targetPublicId:macro.publicId,country});setFlash(req,'success','Saved reply macro created.');res.redirect('/operations/support');}catch(e){next(e);}});
