router.post('/operations/support/tickets/:id/macro',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{const input=z.object({macroPublicId:z.string().trim().min(4).max(120),status:z.enum(['in_progress','waiting_customer','escalated','resolved']).default('in_progress'),internal:z.coerce.boolean().optional().default(false)}).parse(req.body);const t=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user)}).select('+requesterEmailEncrypted');if(!t)throw new AppError('Support ticket not found.',404,'TICKET_NOT_FOUND');const supervisor=['country_admin','super_admin'].includes(req.user.role);if(!t.assignedUserId||(!t.assignedUserId.equals(req.user._id)&&!supervisor))throw new AppError('Claim the ticket before using a saved reply.',409,'TICKET_CLAIM_REQUIRED');const macro=await SupportMacro.findOne({publicId:input.macroPublicId,country:t.country,active:true,$or:[{category:''},{category:t.category}]});if(!macro)throw new AppError('Saved reply is not available for this ticket.',404,'SUPPORT_MACRO_NOT_FOUND');const from=t.status;t.status=input.status;t.notes.push({message:macro.body,actorUserId:req.user._id,internal:input.internal});t.workflowHistory.push({action:'status',actorUserId:req.user._id,fromStatus:from,toStatus:input.status,note:`Applied macro ${macro.publicId}.`});if(input.status==='resolved')t.resolvedAt=new Date();await t.save();if(!input.internal){let recipient=supportRequester(t);if(t.userId){const u=await User.findById(t.userId).select('name email').lean();if(u)recipient={name:u.name,email:u.email};}await sendSupportTicketEmail({email:recipient.email,name:recipient.name,ticketId:t.publicId,subject:`Support ticket ${input.status.replaceAll('_',' ')}`,message:macro.body}).catch(error=>req.log?.warn?.({error:error.message,ticketId:t.publicId},'Support macro email failed'));}res.redirect(`/operations/support/tickets/${encodeURIComponent(t.publicId)}`);}catch(e){next(e);}});
