  const input=z.object({status:z.enum(['in_progress','waiting_customer','escalated','resolved','closed']),message:z.string().trim().min(3).max(2000),internal:z.coerce.boolean().optional().default(false)}).parse(req.body);
  const t=await SupportTicket.findOne({publicId:req.params.id,...supportScope(req.user)}).select('+requesterEmailEncrypted');if(!t)throw new AppError('Ticket not found.',404,'TICKET_NOT_FOUND');
  const supervisor=['country_admin','super_admin'].includes(req.user.role);if(!t.assignedUserId)throw new AppError('Claim the ticket before updating it.',409,'TICKET_CLAIM_REQUIRED');if(!t.assignedUserId.equals(req.user._id)&&!supervisor)throw new AppError('This ticket is assigned to another support operator.',409,'TICKET_ASSIGNED_OTHER');
  const fromStatus=t.status;t.status=input.status;t.notes.push({message:input.message,actorUserId:req.user._id,internal:input.internal});t.workflowHistory.push({action:'status',actorUserId:req.user._id,fromStatus,toStatus:input.status,note:input.internal?'Internal status update':'Customer-facing status update'});if(['resolved','closed'].includes(input.status))t.resolvedAt=new Date();else t.resolvedAt=undefined;await t.save();
  if(!input.internal){let recipient=supportRequester(t);if(t.userId){const u=await User.findById(t.userId).select('name email').lean();if(u)recipient={name:u.name,email:u.email};}await sendSupportTicketEmail({email:recipient.email,name:recipient.name,ticketId:t.publicId,subject:`Support ticket ${input.status.replaceAll('_',' ')}`,message:input.message}).catch(error=>req.log?.warn?.({error:error.message,ticketId:t.publicId},'Support update email failed'));}
