router.post('/operations/support/trust/:id/status',requireAuth,requireVerified,trustOnly,async(req,res,next)=>{try{const input=z.object({status:z.enum(['investigating','actioned','dismissed','closed']),enforcement:z.enum(['none','suspend_product','restore_product','suspend_store','restore_store']).default('none'),decision:z.string().trim().min(3).max(1000)}).parse(req.body);const c=await TrustCase.findOne({publicId:req.params.id,...supportScope(req.user)});if(!c)throw new AppError('Trust case not found.',404,'TRUST_CASE_NOT_FOUND');if(input.status!=='actioned'&&input.enforcement!=='none')throw new AppError('Enforcement requires an actioned trust case.',422,'TRUST_ENFORCEMENT_STATE');if(input.enforcement==='suspend_product'){const product=await Product.findOne({publicId:c.productPublicId});if(!product)throw new AppError('Product not found for enforcement.',404,'PRODUCT_NOT_FOUND');if(product.status!=='suspended'){product.suspension.previousStatus=product.status;product.suspension.reason=input.decision;product.suspension.suspendedAt=new Date();product.suspension.suspendedByUserId=req.user._id;product.status='suspended';await product.save();}}else if(input.enforcement==='restore_product'){const product=await Product.findOne({publicId:c.productPublicId,status:'suspended'});if(!product)throw new AppError('Suspended product not found.',404,'PRODUCT_NOT_FOUND');product.status=['published','approved'].includes(product.suspension?.previousStatus)?product.suspension.previousStatus:'approved';product.suspension.reason='';product.suspension.suspendedAt=undefined;product.suspension.suspendedByUserId=undefined;await product.save();}else if(input.enforcement==='suspend_store'){const store=c.storePublicId?await Store.findOne({publicId:c.storePublicId}):c.productId?await Product.findById(c.productId).then(product=>product?Store.findById(product.storeId):null):null;if(!store)throw new AppError('Store not found for enforcement.',404,'STORE_NOT_FOUND');store.status='suspended';store.suspendedAt=new Date();store.suspensionReason=input.decision;store.suspendedByUserId=req.user._id;await store.save();}else if(input.enforcement==='restore_store'){const store=c.storePublicId?await Store.findOne({publicId:c.storePublicId,status:'suspended'}):c.productId?await Product.findById(c.productId).then(product=>product?Store.findOne({_id:product.storeId,status:'suspended'}):null):null;if(!store)throw new AppError('Suspended store not found.',404,'STORE_NOT_FOUND');store.status='verified';store.suspendedAt=undefined;store.suspensionReason='';store.suspendedByUserId=undefined;await store.save();}c.status=input.status;c.decision=input.decision;c.assignedUserId=req.user._id;if(['actioned','dismissed','closed'].includes(input.status))c.resolvedAt=new Date();await c.save();res.redirect('/operations/support');}catch(e){next(e);}});
router.post('/operations/support/knowledge',requireAuth,requireVerified,supportOnly,async(req,res,next)=>{try{const input=z.object({country:z.string().trim().length(2).optional(),title:z.string().trim().min(4).max(180),slug:z.string().trim().min(3).max(180),body:z.string().trim().min(20).max(12000),category:z.string().trim().min(2).max(80),status:z.enum(['draft','published']).default('draft')}).parse(req.body);const grants=operationalCountriesFor(req.user);const country=String(input.country||(!grants.includes('*')&&grants.length===1?grants[0]:'')).toUpperCase();if(!country)throw new AppError('Choose a country for this knowledge article.',422,'COUNTRY_REQUIRED');if(req.user.role!=='super_admin')assertOperationalCountry(req.user,country);await createKnowledgeArticle(req,{...input,country});res.redirect('/operations/support');}catch(e){next(e);}});
router.get('/api/v1/support/knowledge',async(req,res,next)=>{try{const limit=Math.max(1,Math.min(100,Number(req.query.limit)||50)),base={country:req.country.code,status:'published'};const [rows,total]=await Promise.all([SupportKnowledge.find(cursorScope(base,req.query.after,{field:'publishedAt'})).select('publicId title slug body category publishedAt').sort(cursorSort('publishedAt')).limit(limit+1).lean(),SupportKnowledge.countDocuments(base)]);const page=pageResult(rows,{field:'publishedAt',limit,total});res.json({articles:page.items,page:page.page});}catch(e){next(e);}});
router.post('/operations/support/risks/:id/review',requireAuth,requireVerified,trustOnly,async(req,res,next)=>{try{const input=z.object({status:z.enum(['reviewed','dismissed','actioned']),decision:z.string().trim().min(3).max(1000)}).parse(req.body);const risk=await RiskSignal.findOne({publicId:req.params.id,...supportScope(req.user)});if(!risk)throw new AppError('Risk signal not found.',404,'RISK_NOT_FOUND');risk.status=input.status;risk.decision=input.decision;risk.reviewedByUserId=req.user._id;risk.reviewedAt=new Date();await risk.save();res.redirect('/operations/support');}catch(e){next(e);}});
router.get('/api/v1/reviews/product/:productId',async(req,res,next)=>{try{const limit=Math.max(1,Math.min(100,Number(req.query.limit)||50)),base={productPublicId:req.params.productId,status:'published',country:req.country.code};const [rows,total]=await Promise.all([Review.find(cursorScope(base,req.query.after,{field:'publishedAt'})).select('publicId rating title body verifiedPurchase publishedAt createdAt').sort(cursorSort('publishedAt')).limit(limit+1).lean(),Review.countDocuments(base)]);const page=pageResult(rows,{field:'publishedAt',limit,total});res.set('Cache-Control','public, max-age=30').json({reviews:page.items,page:page.page});}catch(e){next(e);}});

export default router;
